css:
@keyframes blink {
  50% {
    opacity: 0;
  }
}

@keyframes reveal {
  0%,
  60% {
    background: var(--color-accent-soft);
    box-shadow: 0 0 0 0.75rem var(--color-accent-soft);
  }
  to {
    background: transparent;
    box-shadow: 0 0 0 0.75rem transparent;
  }
}

::view-transition-group(root) {
  animation-duration: 180ms;
  animation-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

::view-transition-group(reader-page) {
  animation-duration: 220ms;
  animation-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

:active-view-transition-type(forward)::view-transition-old(reader-page) {
  animation-name: page-out-right;
}

:active-view-transition-type(forward)::view-transition-new(reader-page) {
  animation-name: page-in-from-left;
}

:active-view-transition-type(back)::view-transition-old(reader-page) {
  animation-name: page-out-left;
}

:active-view-transition-type(back)::view-transition-new(reader-page) {
  animation-name: page-in-from-right;
}

@keyframes page-out-right {
  to {
    opacity: 0;
    translate: 2rem 0;
  }
}

@keyframes page-out-left {
  to {
    opacity: 0;
    translate: -2rem 0;
  }
}

@keyframes page-in-from-left {
  from {
    opacity: 0;
    translate: -2rem 0;
  }
}

@keyframes page-in-from-right {
  from {
    opacity: 0;
    translate: 2rem 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }
}

6Iqh7Dtq.css:
transition:
  opacity {transition.duration-pop} {ease.out},
  scale {transition.duration-pop} {ease.out},
  translate {transition.duration-pop} {ease.out},
  display {transition.duration-pop} allow-discrete;
transform-origin: top center;

@starting-style {
  opacity: 0;
  scale: 0.95;
  translate: 0 -8px;
}

&[data-state="closed"] {
  display: none;
  opacity: 0;
  scale: 0.95;
  transition-duration: {transition.duration-pop-exit};
}

@media (prefers-reduced-motion: reduce) {
  transition-property: opacity, display;
}

